const body = $json.body || {};

return [
  {
    json: {
      username: body.username || "",
      user_id: body.user_id || "",
      channel_id: body.channel_id || "",
      channel_name: body.channel_name || "",
      message: body.message || ""
    }
  }
];

const parsed = $('Code in JavaScript').first().json;
const records = $input.all();
let session = { recordId: null, stage: 'NEW', party_size: '', booking_date: '', booking_time: '', proposed_slots: '' };
if (records.length > 0 && records[0].json && records[0].json.id) {
  const rec = records[0].json;
  const f = rec.fields || {};
  session = {
    recordId: rec.id,
    stage: f['State'] || 'NEW',
    party_size: f['Party Size'] || '',
    booking_date: f['Date'] || '',
    booking_time: f['Preferred Time'] || '',
    proposed_slots: f['Notes'] || ''
  };
}
return [{ json: { ...parsed, session } }];

const msg = ($json.message || '').toLowerCase();
const isInterrupt = /cancel|human|agent|representative|talk to someone|real person/.test(msg);
return [{ json: { ...$json, isInterrupt } }];

const rawOutput = $json.output;

const cleaned = rawOutput
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(`Could not parse AI output: ${rawOutput}`);
}

return [
  {
    json: {
      ...$json,
      intent: parsed.intent
    }
  }
];

const msg = $json.message || '';
const match = msg.match(/\d+/);
const partySize = match ? match[0] : '2';
return [{ json: { ...$json, extracted: { party_size: partySize } } }];

const msg = (($json.message || '').trim());
const lower = msg.toLowerCase();
let dateLabel = msg;
const today = new Date();
if (lower === 'today') {
  dateLabel = today.toISOString().slice(0,10);
} else if (lower === 'tomorrow') {
  const t = new Date(today.getTime() + 24*60*60*1000);
  dateLabel = t.toISOString().slice(0,10);
}
return [{ json: { ...$json, extracted: { booking_date: dateLabel } } }];

function parseTimeToMinutes(str) {
  const s = str.trim().toLowerCase();
  const m = s.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/);
  if (!m) return 19 * 60;
  let hour = parseInt(m[1], 10);
  const minute = m[2] ? parseInt(m[2], 10) : 0;
  const ampm = m[3];
  if (ampm === 'pm' && hour < 12) hour += 12;
  if (ampm === 'am' && hour === 12) hour = 0;
  if (!ampm && hour < 8) hour += 12;
  return hour * 60 + minute;
}
function minutesToLabel(mins) {
  mins = ((mins % 1440) + 1440) % 1440;
  let hour = Math.floor(mins / 60);
  const minute = mins % 60;
  const ampm = hour >= 12 ? 'PM' : 'AM';
  let hour12 = hour % 12;
  if (hour12 === 0) hour12 = 12;
  return `${hour12}:${minute.toString().padStart(2,'0')} ${ampm}`;
}
const requested = $json.message || '7 PM';
const baseMinutes = parseTimeToMinutes(requested);
const slots = [baseMinutes - 30, baseMinutes, baseMinutes + 30].map(minutesToLabel);
return [{ json: { ...$json, extracted: { requested_time: requested, proposed_slots: slots } } }];

function normalize(s) {
  return (s || '').toLowerCase().replace(/\s+/g,'').replace(/^0/, '');
}
let slots = [];
try { slots = JSON.parse($json.session.proposed_slots || '[]'); } catch (e) { slots = []; }
const msg = $json.message || '';
const normMsg = normalize(msg);
let confirmed = slots.find(s => normalize(s) === normMsg || normalize(s).includes(normMsg) || normMsg.includes(normalize(s)));
if (!confirmed) confirmed = slots.length > 0 ? slots[Math.floor(slots.length/2)] : msg;
return [{ json: { ...$json, extracted: { confirmed_time: confirmed } } }];

const s = $('Confirm Slot').item.json;
const reply = `🎉 You're all set! Table for ${s.session.party_size} on ${s.session.booking_date} at ${s.extracted.confirmed_time} is confirmed. See you then!`;
return [{ json: { reply } }];
